      "\uC0AC\uBB34\uAD00",
      "\uC11C\uAE30\uAD00",
      "\uC5F0\uAD6C\uAD00",
      "\uC5F0\uAD6C\uC0AC",
      "\uC870\uC0AC\uAD00",
      "\uC218\uC0AC\uAD00",
      "\uAC10\uB3C5\uAD00",
      "\uC2EC\uC0AC\uAD00",
