        re: new RegExp(`${NB}(?<n>${hangulName(ALL_SURNAMES, () => "\\s?[(\uFF08]\\s?(?:\uB9CC\\s?\\d{1,3}\\s?\uC138|\\d{1,3}\\s?\uC138|\uC5EC|\uB0A8|\u5973|\u7537)\\s?[,\uFF0C)\uFF09]")})`, "dg"),
        span: "n",
        mask: NAME_MASK,
