        // 강한 문맥("편도윤 담당자(☎ …)")
        re: new RegExp(`${NB}(?<n>${hangulName(ALL_SURNAMES, () => `(?:\\s|<br>)(?:\uC81C\\d{1,2}\\s?)?(?:${TITLE_RE})(?:\uB2D8)?(?:${P_ALL})?(?![\uAC00-\uD7A3])`)})(?:(?<after>(?:\\s|<br>)(?:${TITLE_RE})${PHONE_NEXT})|(?<weak>(?:\\s|<br>)(?:${TITLE_AFTER_RE})(?:\uB2D8)?(?:${P_ALL})?(?![\uAC00-\uD7A3])))`, "dg"),
        span: "n",
