        re: new RegExp(`(?:^|\\||<t[dh][^>]*>)\\s*\u4EE3\\s?(?<n>${hangulName(ALL_SURNAMES, () => "\\s*(?:\\||<\\/t[dh]>|$)")})`, "dg"),
        span: "n",
        mask: NAME_MASK,
